const now = new Date();
const hour = now.getHours();
const minute = now.getMinutes();
let gateWindow = 'strategic';
if (hour === 10 && minute === 45) gateWindow = 'operational';
if (hour === 14 && minute === 45) gateWindow = 'quality';
const missionId = `ritual-${gateWindow}-${now.toISOString().slice(0,10)}`;
return [{
  json: {
    eventType: `ritual.${gateWindow}`,
    gateWindow,
    mission: {
      tenantId: '00000000-0000-0000-0000-000000000001',
      missionId,
      runId: `${missionId}-run`,
      taskId: `${missionId}-task`,
      dprId: `${missionId}-dpr`,
      triggerSource: 'n8n.scheduler'
    },
    generatedAt: now.toISOString()
  }
}];

const item = items[0].json;
const gate = item.gateWindow;
const requiredByGate = {
  strategic: ['strategicPriorities', 'blockedDecisions'],
  operational: ['costAudit', 'healthMetrics', 'confidenceFlags'],
  quality: ['qaHealth', 'releaseRisk', 'exceptions']
};
const required = requiredByGate[gate] || [];
const missingSections = required.filter((k) => item[k] === undefined || item[k] === null);
const confidence = missingSections.length === 0 ? 95 : 70;
item.partialReport = missingSections.length > 0;
item.confidence = confidence;
item.missingSections = missingSections;
item.summary = `[${gate.toUpperCase()} Gate] confidence=${confidence}% partial=${item.partialReport}`;
return [{ json: item }];
